{
  "classifications": [
    {
      "document_id": "246",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text commemorates the 100th birthday of a Texas artist and provides biographical information. There is no claim of the senator producing a concrete benefit, securing funds, or receiving an award, so it is not credit-claiming."
    },
    {
      "document_id": "4121",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The release describes the senator attending a bill signing at the White House and praising the legislation. It does not present the senator as personally responsible for authoring the bill, securing its passage, or producing a specific benefit, so it is not credit-claiming."
    },
    {
      "document_id": "3781",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The release announces a news conference and describes legislative actions (filing a resolution and a motion) without claiming a completed or successful legislative outcome or concrete benefit. The rule states that merely describing legislation without claiming success is not credit-claiming."
    },
    {
      "document_id": "2871",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text expresses the senator's disappointment with the Attorney General's testimony. It is a criticism of an executive branch official and does not claim a secured concrete benefit or legislative success."
    },
    {
      "document_id": "3752",
      "label": "1",
      "codebook_rule": [
        "1",
        "2",
        "5"
      ],
      "explanation": "The text announces the Senate passage of an amendment authored by the senator ('Senate passes Menendez amendment' and 'passage of his amendment'). This claims personal responsibility for winning passage of a provision, announces an adopted amendment as his accomplishment, and explicitly connects a named amendment to the senator."
    },
    {
      "document_id": "723",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The release announces that the senator 'welcomes approval' of funding for a local sewer treatment plant by a Senate committee. However, it does not state or strongly imply that the senator personally brought about this concrete outcome or present her as personally responsible for securing the funds."
    },
    {
      "document_id": "3260",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The release states that 'Last year, Coleman led a similar effort, ultimately helping to fend off deep cuts to the overall agriculture budget,' and quotes him saying 'Since 2003, I have successfully led bipartisan efforts in the U.S. Senate to protect this farm bill.' This credits the senator with blocking or preventing an undesirable outcome (cuts to agriculture) and presents him as responsible for that result."
    },
    {
      "document_id": "769",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text is a speech by the senator expressing his policy positions, criticizing the Military Commissions Act, and advocating for grassroots action to restore habeas corpus. It does not claim a concrete legislative accomplishment or benefit secured by the senator."
    },
    {
      "document_id": "2354",
      "label": "1",
      "codebook_rule": [
        "1",
        "2",
        "5"
      ],
      "explanation": "The text explicitly claims that the senator 'has secured funding in Senate appropriations legislation for many important agriculture and rural initiatives,' making him personally responsible for obtaining funding. It also notes that he 'authored provisions in the 2002 farm bill creating the CSP,' explicitly connecting him to a program as its author."
    },
    {
      "document_id": "1602",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text describes the senator visiting local businesses, hosting town halls, explaining his policy positions, and introducing legislation (the Border Security First Act). It does not claim that he secured a concrete benefit, passed a law, or received an award, so it does not meet the criteria for credit-claiming."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "1898",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senators are merely announcing their support and future intentions to help bring a facility to Georgia. They have not yet secured a concrete outcome, so this does not meet any credit-claiming rules."
    },
    {
      "document_id": "799",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The headline explicitly states that the senators \"secure[d] $181 million\" for R&D projects to benefit Maine. This directly frames the senators as personally responsible for obtaining a concrete funding outcome, satisfying Rule 1."
    },
    {
      "document_id": "3262",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senators are announcing a concrete financial benefit—a $26,590 federal grant—for a university in their state. Per the codebook's definition, announcing funds or grants secured for the state qualifies as credit-claiming because it strongly implies the senators were responsible for obtaining the funding (Rule 1)."
    },
    {
      "document_id": "450",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator is discussing a pending amendment to a bill being debated and expressing hope that it gets approved. He does not claim that the amendment has been adopted or that he has secured a concrete outcome, so it does not meet the criteria for credit-claiming."
    },
    {
      "document_id": "2974",
      "label": "1",
      "codebook_rule": [
        "1",
        "4"
      ],
      "explanation": "The text states that the senator sought assurances from the administration to prevent the downgrade of the Space Command and successfully received that commitment. This satisfies Rule 1 for preventing an undesirable action and Rule 4 for using intervention/pressure to secure a concrete decision."
    },
    {
      "document_id": "340",
      "label": "1",
      "codebook_rule": [
        "2",
        "5"
      ],
      "explanation": "The release announces the Senate passage of a transit security bill and explicitly identifies it as \"Chairman Dodd's bill,\" connecting the senator to the authored legislation and claiming its passage as an accomplishment. This satisfies Rules 2 and 5."
    },
    {
      "document_id": "2980",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senator is announcing a concrete financial benefit—a $75,000 federal grant—for a planning commission in his state. Announcing targeted federal funding secured for the state strongly implies the senator's role in obtaining the outcome, which satisfies Rule 1."
    },
    {
      "document_id": "1292",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text describes the senator re-introducing legislation. It does not announce a completed legislative accomplishment or secured outcome, so it does not meet the criteria for credit-claiming."
    },
    {
      "document_id": "1579",
      "label": "1",
      "codebook_rule": [
        "2",
        "5"
      ],
      "explanation": "The text announces that a Senate committee passed a piece of legislation, explicitly identifying it as \"Sen. Dodd's bill.\" This meets Rule 2 for claiming a committee-approved bill as a legislative accomplishment and Rule 5 for explicitly connecting the bill to the senator as its sponsor."
    },
    {
      "document_id": "2780",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The release discusses a newly released public health report and urges Congress to pass legislation the senator previously co-sponsored. Because the legislation has not yet passed and the senator is advocating for future action rather than claiming a secured outcome, this is not credit-claiming."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "3868",
      "label": "1",
      "codebook_rule": [
        "1",
        "2",
        "5"
      ],
      "explanation": "The release explicitly states that Senators Leahy and Bond \"succeeded in designating\" and \"secured the $2.44 billion in federal funds\" for the National Guard (satisfying Rule 1). It also highlights a legislative accomplishment by noting that \"The Bond Leahy Amendment was passed\" (satisfying Rule 2), and explicitly connects the named amendment to the senators as its authors and the cause of its success (satisfying Rule 5)."
    },
    {
      "document_id": "1950",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The document announces that specific fire departments will receive federal grants, which falls under the definition of announcing funds secured for the state. It strongly implies the senator's responsibility by stating that \"Schumer Has Pushed For Additional Funding\" and that he \"was among the first senators who recognized the need for the federal government to establish a funding program,\" satisfying Rule 1."
    },
    {
      "document_id": "3050",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The release announces a concrete financial benefit for the state—a $2.14 million FEMA grant for the Orleans Parish Criminal Sheriff's Office. By making this announcement and stating his commitment to \"continue my efforts... to bring additional resources to Louisiana,\" the senator strongly implies his personal role in obtaining this funding, satisfying Rule 1."
    },
    {
      "document_id": "2429",
      "label": "1",
      "codebook_rule": [
        "1",
        "4"
      ],
      "explanation": "The text directly states that \"Senator Gregg has secured $28 million\" for a local project, meeting Rule 1. Additionally, it quotes local officials praising and thanking Senator Gregg for \"his efforts in securing this funding\" and his \"ongoing support,\" demonstrating that his advocacy produced a concrete benefit for the community, which satisfies Rule 4."
    },
    {
      "document_id": "2066",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text is a statement expressing the senator's disappointment regarding a judicial ruling on the Yucca Mountain project and criticizing the Department of Energy. It states a future intention (\"I will continue working\"), but does not claim any concrete past achievement, benefit secured, or policy outcome. Therefore, it is not credit-claiming."
    },
    {
      "document_id": "182",
      "label": "0",
      "codebook_rule": [],
      "explanation": "This press release is a critical response to the President's State of the Union address. It focuses on expressing policy positions and criticizing the opposing party/administration. It does not claim credit for any concrete benefit, policy outcome, or legislative achievement, so it does not meet any credit-claiming rules."
    },
    {
      "document_id": "1805",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The document describes the senator's oversight activities, such as questioning the Navy Secretary during a committee hearing and sending a letter to the President regarding acquisition strategy. Because it merely describes oversight and meetings without claiming a secured result or policy change, it is not credit-claiming."
    },
    {
      "document_id": "234",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The release describes legislation that was passed by Congress and includes quotes from Senator Kyl expressing his pleasure with the bill's passage and criticizing Democrats. However, it does not present the senator as personally responsible for authoring the bill or securing its passage. Describing legislation without claiming personal success is not credit-claiming."
    },
    {
      "document_id": "363",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The document is a statement outlining the senator's policy views on immigration and border security. Although he mentions proposing a bipartisan bill, introducing or proposing legislation without claiming it passed or produced a concrete outcome is merely an expression of policy positions and legislative activity, not credit-claiming."
    },
    {
      "document_id": "477",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senator is announcing a concrete federal grant of over $5.7 million for an airport in his state. According to the codebook definition, announcing funds or grants secured for the state is considered credit-claiming, as it serves to present the senator as delivering these federal resources to constituents, thereby satisfying Rule 1."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "4166",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator expresses outrage and sends a letter requesting the Secretary of State's personal attention, but does not claim to have personally brought about a concrete outcome, secured a legislative accomplishment, or obtained an award. This is an expression of a policy position and oversight without a claimed result."
    },
    {
      "document_id": "666",
      "label": "1",
      "codebook_rule": [
        "1",
        "2"
      ],
      "explanation": "The senator explicitly connects his past legislative action (\"actively worked to clarify that congressional intent prior to the votes on this matter in the Senate\") to the Supreme Court's favorable ruling on the Detainee Treatment Act. By claiming he is responsible for clarifying the congressional intent that the Court relied upon, he attributes a concrete policy outcome and a legislative accomplishment to his own efforts."
    },
    {
      "document_id": "3944",
      "label": "1",
      "codebook_rule": [
        "1",
        "3"
      ],
      "explanation": "The senator is explicitly presented as receiving an award/honor from an external organization (\"named U.S. Senator Herb Kohl as a champion for small manufacturers\"). The text also claims the senator successfully secured funding (\"Kohl led a bipartisan group of Senators in the fight to fund the MEP program at $106 million\")."
    },
    {
      "document_id": "3745",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator issues a statement criticizing the administration's proposed military commissions legislation and citing the opposition of retired military officers and judges. The text expresses policy positions and criticizes opponents, but does not claim any concrete personal accomplishment, secured outcome, or award."
    },
    {
      "document_id": "4526",
      "label": "1",
      "codebook_rule": [
        "1",
        "4"
      ],
      "explanation": "The release claims that the senator's intervention (\"Ensign has received a response to his directive that the Federal Aviation Administration (FAA) deal quickly with failures...\") directly produced a concrete remedy for the airport. The FAA responded to his letter by completing equipment repairs and scheduling modifications to prevent future issues, framing the senator as responsible for securing this concrete result."
    },
    {
      "document_id": "4017",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senators are described as sending a letter to the Senate Budget Committee to urge them to protect Medicaid funding and oppose cuts. The text announces a policy position and advocacy effort, but does not claim any completed legislative accomplishment or secured outcome."
    },
    {
      "document_id": "1034",
      "label": "1",
      "codebook_rule": [
        "2",
        "5"
      ],
      "explanation": "The text states that \"Senator Kennedy passed an amendment last August requiring Negroponte to task the intelligence community to prepare an updated NIE.\" This claims a legislative accomplishment (passing an amendment) and explicitly connects the senator as the author of that provision, satisfying the criteria for credit-claiming."
    },
    {
      "document_id": "733",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator is described as \"urging the Senate Appropriations Subcommittee... to fully fund the federal government's share of the Individuals with Disabilities Education Act.\" This is an expression of future intentions and advocacy, but it does not announce a secured outcome, obtained funding, or legislative accomplishment."
    },
    {
      "document_id": "3851",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text announces that the senators \"introduced comprehensive border security and immigration reform legislation\". As stated in the codebook's negative example for Rule 2, introducing legislation without claiming it passed or secured a concrete outcome is not credit-claiming."
    },
    {
      "document_id": "4794",
      "label": "1",
      "codebook_rule": [
        "2",
        "5"
      ],
      "explanation": "The senator explicitly connects himself to the creation of a named program, stating \"Sen. John Rockefeller (D-WV) and I established the E-Rate program in 1996.\" Claiming authorship and creation of a program constitutes credit-claiming under the rules for legislative accomplishments and connecting a program to the senator as its author."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "4809",
      "label": "1",
      "codebook_rule": [
        "1",
        "2"
      ],
      "explanation": "The text claims that Senator Dole achieved concrete policy outcomes and legislative successes despite her opposition to the final overall bill. It notes that she successfully raised fuel economy standards, defeated an amendment regarding offshore drilling, blocked a federal Renewable Portfolio Standard, and stopped a tax increase. This satisfies Rule 1 for blocking actions and bringing about policy changes, and Rule 2 for securing the adoption or defeat of specific amendments."
    },
    {
      "document_id": "4243",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text describes Senator Boxer sending letters to urge action on interoperable communications and air cargo screening. This is an example of expressing policy positions and advocating for action, but since it does not claim that her intervention produced a concrete outcome or secured a result, it is not credit-claiming."
    },
    {
      "document_id": "731",
      "label": "1",
      "codebook_rule": [
        "2",
        "5"
      ],
      "explanation": "While the subject of the text is commemorative (honoring a centennial), the text does not merely commemorate an event. Instead, it announces a legislative accomplishment: the Senate's passage of S. Res. 297, which the text explicitly connects to Senator Hatch as its author and Senator Bennett as a cosponsor. This satisfies Rule 2 (claiming passage of a legislative item) and Rule 5 (asserting authorship of a named resolution)."
    },
    {
      "document_id": "1816",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text describes Senator Cornyn welcoming the opening of a new production facility and delivering a certificate of appreciation. Although it highlights economic benefits to the local community, it does not claim that the senator was personally responsible for securing the facility, producing the outcome, or obtaining funding. Therefore, it does not meet the criteria for credit-claiming."
    },
    {
      "document_id": "2874",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text contains a statement by Senator Stabenow criticizing the President's veto of a health care bill. It functions as a policy objection and criticism of an opponent without claiming any concrete outcome, legislative success, or achievement produced by the senator. Thus, it is not credit-claiming."
    },
    {
      "document_id": "1622",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text features Senator Gregg criticizing a recently passed bill and outlining his policy objections. While he mentions an alternative proposal he supported, the text does not claim that he successfully secured an outcome, passed a provision, or produced a concrete benefit. Expressing policy positions and criticizing legislation is not credit-claiming."
    },
    {
      "document_id": "785",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text announces the introduction of a legislative measure by Senators Feinstein and Ensign. Because it only describes the introduction of a bill and future legislative intentions without claiming the successful passage or securing of a concrete outcome, it does not qualify as credit-claiming."
    },
    {
      "document_id": "2967",
      "label": "1",
      "codebook_rule": [
        "1",
        "2",
        "5"
      ],
      "explanation": "The text explicitly claims a legislative success by announcing that Congress has given final approval to the \"Clinton Proposal\" and an amendment she introduced. It frames the senator as responsible for a concrete policy outcome (Rule 1), attributes a legislative accomplishment to her (Rule 2), and explicitly connects her to a named measure/amendment as its author (Rule 5)."
    },
    {
      "document_id": "412",
      "label": "1",
      "codebook_rule": [
        "1",
        "2",
        "5"
      ],
      "explanation": "The text announces almost $7 million in federal funding for local airports and explicitly attributes this outcome to the senators by stating the awards \"directly result from a bill authored by Sen. Lott and cosponsored by Sen. Cochran.\" This claims the securing of concrete funding (Rule 1), attributes a legislative achievement to the senators (Rule 2), and connects the senators to the drafting and authorship of the successfully passed legislation (Rule 5)."
    },
    {
      "document_id": "2086",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The text describes Senator Clinton and others introducing a bill and notes her leadership and advocacy on pay equity issues (e.g., \"Senator Clinton has been a leading voice,\" \"co-hosted a Pay Equity for Women seminar\"). However, it only announces a bill introduction and describes reputational efforts without claiming a successfully secured outcome, passed legislation, or concrete policy benefit. Thus, it is not credit-claiming."
    }
  ]
}

{
  "classifications": [
